use vstd::prelude::*;

verus! {
    // Specification for the ones function
    fn ones(n: usize) -> (result: Vec<i8>)
        ensures
            result.len() == n,
            forall |i: usize| 0 <= i < n ==> result[i] == 1,
            forall |i: usize, j: usize| 0 <= i < n && 0 <= j < n ==> result[i] == result[j],
            forall |i: usize| 0 <= i < n ==> result[i] > 0,
    {
        // Create a vector of length n initialized with 1s
        let mut result: Vec<i8> = Vec::new();
        let mut idx: usize = 0;

        // Loop to fill the vector with 1s
        while idx < n
            invariant
                idx <= n,
                result.len() == idx,
                forall |i: usize| 0 <= i < idx ==> result[i] == 1,
                forall |i: usize, j: usize| 0 <= i < idx && 0 <= j < idx ==> result[i] == result[j],
                forall |i: usize| 0 <= i < idx ==> result[i] > 0,
            decreases n - idx,
        {
            result.push(1); // Push 1 into the vector
            idx = idx + 1; // Increment the index
        }

        result // Return the constructed vector
    }
}

